(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.headline":"<span class=\"hl-muted\">Xem đôi tay thật chơi nhạc của bạn.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\" data-words=\"Then drag it into your DAW.|Read every note.|Learn how it is played.\">Rồi kéo nó vào DAW của bạn.</span>","hero.cycle":"Rồi kéo nó vào DAW của bạn.|Đọc từng nốt nhạc.|Học cách chơi nó.","hero.sub":"Hợp âm, một giai điệu, một dòng bass và một giai điệu đối, được viết theo bất kỳ phong cách nào, hiển thị thành bốn tờ bản nhạc và được đôi tay chân thực chơi trên một cây đàn piano chân thực. Ngoại tuyến và 100% không dùng AI.","hero.chipStandalone":"Ứng dụng độc lập","what.title":"Đây là gì","what.p1":"Phần lớn nhà sản xuất dùng trình tạo hợp âm chưa bao giờ thấy các phần nhạc của nó sẽ được chơi như thế nào. Handscore cho bạn thấy.","what.p2":"Chọn một thể loại, một nghệ sĩ hoặc một nhà sản xuất, và Handscore viết bốn phần nhạc theo phong cách đó: hợp âm, một giai điệu, một dòng bass và một giai điệu đối. Chúng hiện ra thành bốn tờ bản nhạc trên giá nhạc của cây đàn piano, và một đôi tay chân thực chơi chúng trên một cây đàn piano chân thực, mỗi ngón tay đặt trên đúng phím mà một nghệ sĩ piano sẽ dùng.","what.p3":"Mỗi phím mang tên của nó ở mặt trước, nên bạn thấy chính xác những nốt nào đang được chơi. Khi một phần đã ưng ý, hãy kéo nó từ tờ nhạc của nó thẳng lên một track trong DAW của bạn.","inside.title":"Nó sẽ làm được gì","inside.pianos.title":"Những cây piano thật","inside.pianos.body":"Một cây đại dương cầm, một cây piano cơ, một cây piano đứng và một cây piano honky-tonk, mỗi cây được chơi bằng cùng những giọng piano đã đo đạc như của Freally MIDI Master.","inside.hands.title":"Đôi tay chân thực","inside.hands.body":"Hai bàn tay chơi mọi nốt bằng đúng ngón tay mà một nghệ sĩ piano sẽ chọn, nhấn từng phím xuống đúng lúc nó vang lên.","inside.sheets.title":"Bốn tờ bản nhạc","inside.sheets.body":"Hợp âm, giai điệu, giai điệu đối và bass, mỗi phần trên một tờ riêng, với mọi nốt sáng lên khi được chơi.","inside.styles.title":"Mọi phong cách mà Freally MIDI Master biết","inside.styles.body":"73 thể loại, 1.507 nghệ sĩ và 833 nhà sản xuất, từ cùng những bộ tạo dựa trên quy tắc.","inside.drag.title":"Kéo MIDI","inside.drag.body":"Từng phần một hoặc cả bốn cùng lúc, kéo từ các tờ nhạc thẳng vào DAW của bạn. Đó là cách duy nhất để MIDI rời khỏi Handscore.","inside.views.title":"Góc nhìn phía trước, từ trên xuống và từ bên cạnh","inside.views.body":"Chuyển giữa các góc nhìn trong khi nhạc đang phát; các tờ nhạc xoay theo để luôn dễ đọc và đôi tay không bao giờ bỏ lỡ một nốt nào.","inside.daw.title":"Trong mọi DAW","inside.daw.body":"CLAP, VST3 và AU, cùng một ứng dụng độc lập. Windows, macOS và Linux.","inside.offline.title":"Ngoại tuyến, không AI","inside.offline.body":"Không tài khoản, không đo lường từ xa, không mạng, không mô hình. Mọi phần nhạc, cách bấm ngón và chuyển động đều đến từ các quy tắc, được một cổng kiểm tra khi dựng bảo đảm chứ không chỉ là lời hứa.","ladder.title":"Con đường đến 1.0, và tiếp tới 2.0","ladder.intro":"Mỗi phiên bản một dòng. Sau 1.0, mỗi phiên bản mang đến một họ nhạc cụ mới, được đôi tay chân thực chơi theo cách một giáo viên sẽ chỉ cho bạn.","ladder.rung.v0.1.0":"Nền móng: plugin tải được dưới dạng CLAP, VST3 và AU lẫn ứng dụng độc lập, đề nghị bạn chấp nhận giấy phép, và mở ra một bàn phím 88 phím với tên của mọi phím.","ladder.rung.v0.2.0":"Những cây piano thật: đại dương cầm, piano cơ, piano đứng và honky-tonk, với các phím chuyển động và vang lên khi chơi.","ladder.rung.v0.3.0":"Đôi tay chân thực trên bàn phím, bấm ngón mọi nốt theo cách một nghệ sĩ piano sẽ làm.","ladder.rung.v0.4.0":"Tạo nhạc theo bất kỳ phong cách nào, đọc bốn tờ nhạc khi chúng sáng lên, và kéo MIDI vào DAW của bạn.","ladder.rung.v0.5.0":"Góc nhìn từ trên xuống và từ bên cạnh, với các tờ nhạc nằm phẳng trên đàn piano, và chuyển đổi liền mạch giữa các góc nhìn.","ladder.rung.lessons-1":"Học từ ngày đầu tiên: một khóa piano lắng nghe bạn chơi và chuyển sang phần tiếp theo khi bạn đã chơi đúng, mỗi bài học được đọc thành tiếng, với từng chữ sáng lên khi được đọc tới.","ladder.rung.mixer":"Một mixer cho từng phần nhạc, với fader, pan, EQ, hiệu ứng và nén, và bản mix được giữ nguyên khi kéo ra.","ladder.rung.song-view":"Chế độ xem Bài hát: tự tay dựng cả một bài hát từ các đoạn, hoặc bắt đầu từ bản phối của một nghệ sĩ hay một thể loại, rồi xem bài hát được chơi và kéo nó vào DAW của bạn.","ladder.rung.lessons-2":"Thêm các khóa học: đọc bản nhạc, tiết tấu, luyện tai, nhạc lý với Nashville Number System, sáng tác ca khúc và viết lời, phối khí và mix.","ladder.rung.finger-drumming":"Finger drumming trên bộ điều khiển pad có các pad sáng lên theo từng cú gõ, từ nhịp đầu tiên đến những groove hoàn chỉnh.","ladder.rung.live-listening":"Nghe trực tiếp: chơi một nhạc cụ thật qua micro hoặc dây cáp nhạc cụ, và các bài học sẽ nghe thấy.","ladder.rung.guitars":"Các cây guitar: guitar thùng, guitar dây nylon, guitar điện và guitar chặn tiếng, với cách bấm phím, gảy dây và quạt dây thật.","ladder.rung.bass":"Guitar bass, chơi bằng ngón tay và bằng kỹ thuật slap.","ladder.rung.own-audio":"Âm thanh và MIDI của riêng bạn, được đọc thành các phần nhạc và được đôi tay chơi lại.","ladder.rung.classics":"Nhạc kinh điển: những giai điệu thuộc phạm vi công cộng để xem và nghe.","ladder.rung.realism":"Lượt trau chuốt độ chân thực: ánh sáng, chất liệu và chuyển động được đối chiếu với cảnh chơi đàn quay thật.","ladder.rung.finish":"Hoàn thiện: phần cài đặt, mười tám ngôn ngữ ở mọi nơi, khả năng tiếp cận và tài liệu hướng dẫn.","ladder.rung.v1.0.0-beta.1":"Thông báo cập nhật cùng các phiên bản dùng thử và trả phí.","ladder.rung.v1.0.0":"Bản phát hành công khai đầu tiên.","ladder.rung.v1.1.0":"Piano điện và organ, trong đó organ có bàn phím pedal để chơi dòng bass.","ladder.rung.v1.2.0":"Đàn harpsichord, clavinet, celesta và piano đồ chơi; ukulele, banjo và mandolin.","ladder.rung.v1.3.0":"Nhạc cụ gõ dùng dùi: xylophone, marimba, vibraphone và glockenspiel.","ladder.rung.v1.4.0":"Đàn hạc, koto, sitar và dulcimer núi.","ladder.rung.v1.5.0":"Violin, viola, cello và double bass, kéo vĩ và gảy dây.","ladder.rung.v1.6.0":"Sáo flute, clarinet, các loại saxophone, oboe và sáo recorder.","ladder.rung.v1.7.0":"Kèn trumpet, kèn trombone, kèn cor và kèn tuba.","ladder.rung.v1.8.0":"Một bộ trống được sắp đặt và chơi theo cách một tay trống chuyên nghiệp sẽ làm.","ladder.rung.v1.9.0":"Chơi theo và chế độ học.","ladder.rung.v2.0.0":"Ban nhạc: mỗi phần trên nhạc cụ riêng, mỗi nhạc cụ có người chơi riêng.","ladder.note":"Một phiên bản hoàn tất đã được dựng và gắn thẻ. Đó không phải là bản tải xuống: chưa có bản tải xuống nào trước 1.0.0.","honest.title":"Hiện giờ nó đang ở đâu","honest.start.title":"Nó đang ở những bước đầu tiên","honest.start.body":"Phiên bản 0.2.0 nạp được trong DAW và mở ra bốn cây piano thật với tên của mọi phím, mà bạn chơi bằng chuột hoặc từ DAW của mình. Đôi tay và các tờ nhạc sẽ đến dần qua từng phiên bản, như chiếc thang ở trên cho thấy.","honest.downloads.title":"Chưa có bản tải xuống nào trước 1.0.0","honest.downloads.body":"Không có bản beta trên trang này, không có bản dựng thử và không có quyền truy cập sớm.","honest.network.title":"Nó không bao giờ lên mạng","honest.network.body":"Plugin và ứng dụng độc lập không chứa mã mạng nào, và một cổng kiểm tra khi dựng sẽ thất bại nếu có mã như vậy được thêm vào. Một phiên bản sau này có thể thêm một tính năng kiểm tra cập nhật, luôn tắt trừ khi bạn tự bật lên, được chạy bởi một chương trình riêng biệt.","site.tagline":"Xem đôi tay thật chơi nhạc của bạn. Rồi kéo nó vào DAW của bạn.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © 2026 Mike Weaver, kinh doanh dưới tên Havoc Software. Không phải mã nguồn mở.","footer.yours":"MIDI bạn tạo ra và kéo vào DAW là của bạn. Tác giả của Handscore không nhận bất kỳ quyền sở hữu nào đối với nó.","featuresPage.lead":"Bốn phần nhạc được viết theo bất kỳ phong cách nào, hiển thị thành bản nhạc và được đôi tay chân thực chơi trên một nhạc cụ chân thực — và mọi phần đều kéo thẳng được vào DAW của bạn.","featuresPage.version":"Trang này mô tả những gì Freally Handscore phiên bản 1.0 sẽ làm được. Phiên bản hiện tại là 0.2.0: xem con đường đến 1.0 trên trang chủ.","featuresPage.numbers.parts":"phần: hợp âm, giai điệu, giai điệu đối và bass","featuresPage.numbers.genres":"thể loại","featuresPage.numbers.artists":"nghệ sĩ","featuresPage.numbers.producers":"nhà sản xuất","featuresPage.numbers.keys":"phím, mỗi phím ghi tên ở mặt trước","featuresPage.numbers.plugins":"định dạng plugin, cùng một ứng dụng độc lập","featuresPage.numbers.languages":"ngôn ngữ","featuresPage.numbers.ai":"mô hình AI","featuresPage.free.title":"Miễn phí hôm nay","featuresPage.free.body":"Handscore hiện miễn phí: không có gói trả phí, không thuê bao và không tài khoản. Hiện chưa có gì để tải xuống, vì không có bản tải xuống nào trước phiên bản 1.0.0, và các phiên bản sau này có thể được bán.","featuresPage.cards.title":"Phiên bản 1.0 làm được gì","featuresPage.cards.pianos.title":"Bốn cây piano thật","featuresPage.cards.pianos.body":"Một cây đại dương cầm, một cây piano cơ, một cây piano đứng và một cây piano honky-tonk, mỗi cây có các phím chuyển động khi vang lên, và được chơi bằng cùng những giọng piano đã đo đạc như của Freally MIDI Master.","featuresPage.cards.strings.title":"Guitar và guitar bass","featuresPage.cards.strings.body":"Guitar thùng, guitar dây nylon, guitar điện và guitar chặn tiếng, với cách bấm phím, gảy dây và quạt dây thật, cùng guitar bass, chơi bằng ngón tay và bằng kỹ thuật slap.","featuresPage.cards.hands.title":"Đôi tay chân thực","featuresPage.cards.hands.body":"Hai bàn tay chơi mọi nốt theo cách một người chơi đàn sẽ chơi: đúng ngón tay mà một nghệ sĩ piano sẽ chọn, đúng ngăn phím và cú gảy mà một nghệ sĩ guitar sẽ dùng.","featuresPage.cards.sheets.title":"Bốn tờ bản nhạc","featuresPage.cards.sheets.body":"Hợp âm, giai điệu, giai điệu đối và bass, mỗi phần trên một tờ riêng, với mọi nốt sáng lên khi được chơi.","featuresPage.cards.styles.title":"Mọi phong cách mà Freally MIDI Master biết","featuresPage.cards.styles.body":"Chọn một trong 73 thể loại, 1.507 nghệ sĩ hoặc 833 nhà sản xuất, và cùng những bộ tạo dựa trên quy tắc sẽ viết bốn phần nhạc theo phong cách đó.","featuresPage.cards.yours.title":"Âm thanh và MIDI của riêng bạn","featuresPage.cards.yours.body":"Đưa vào âm thanh hoặc MIDI của riêng bạn, và Handscore sẽ đọc nó thành các phần nhạc để đôi tay chơi.","featuresPage.cards.classics.title":"Nhạc kinh điển","featuresPage.cards.classics.body":"Những bản nhạc thuộc phạm vi công cộng để xem và nghe. Chúng chỉ được phát, và không bao giờ rời khỏi Handscore.","featuresPage.cards.drag.title":"Kéo MIDI","featuresPage.cards.drag.body":"Từng phần một hoặc cả bốn cùng lúc, kéo từ các tờ nhạc thẳng vào DAW của bạn. Đó là cách duy nhất để MIDI rời khỏi Handscore.","featuresPage.cards.views.title":"Góc nhìn phía trước, từ trên xuống và từ bên cạnh","featuresPage.cards.views.body":"Chuyển giữa các góc nhìn trong khi nhạc đang phát; các tờ nhạc xoay theo để luôn dễ đọc và đôi tay không bao giờ bỏ lỡ một nốt nào.","featuresPage.cards.daw.title":"Trong mọi DAW","featuresPage.cards.daw.body":"CLAP và VST3 trên Windows, macOS và Linux, AU trên macOS, cùng một ứng dụng độc lập để làm việc mà không cần DAW.","featuresPage.cards.offline.title":"Ngoại tuyến, không AI","featuresPage.cards.offline.body":"Không tài khoản, không đo lường từ xa, không mạng và không mô hình. Mọi phần nhạc, cách bấm ngón và chuyển động đều đến từ các quy tắc.","featuresPage.compare.title":"Đặt cạnh nhau","featuresPage.compare.intro":"Freally Handscore 1.0 đặt cạnh những công cụ mà mọi người dùng để viết các phần nhạc hoặc để xem piano được chơi. Các ô của sản phẩm khác lấy từ thông tin công khai và các bài đánh giá về chúng, được kiểm tra vào tháng 10 năm 2026; chỗ nào chúng tôi không thể xác nhận, ô đó sẽ ghi rõ.","featuresPage.compare.feature":"Tính năng","featuresPage.compare.row.generate":"Viết hợp âm, giai điệu và dòng bass mới theo các phong cách được gọi tên","featuresPage.compare.legend.yes":"có","featuresPage.compare.legend.no":"không","featuresPage.compare.row.plugin":"Chạy bên trong DAW của bạn dưới dạng plugin","featuresPage.compare.row.hands":"Hiển thị đôi tay 3D chân thực chơi các nốt","featuresPage.compare.note.library":"thư viện bản nhạc riêng","featuresPage.compare.legend.part":"một phần","featuresPage.compare.note.fingers":"số ngón tay, không có bàn tay","featuresPage.compare.row.sheets":"Hiển thị các nốt dưới dạng bản nhạc","featuresPage.compare.legend.unknown":"chưa xác nhận","featuresPage.compare.row.drag":"Kéo MIDI vào DAW của bạn","featuresPage.compare.row.offline":"Hoạt động ngoại tuyến, không dùng AI","featuresPage.compare.summaryTitle":"Tóm lại","featuresPage.compare.summary":"Trong bốn sản phẩm này, chỉ Handscore 1.0 có đủ mọi hàng: các phần nhạc được viết theo các phong cách được gọi tên, đôi tay chân thực chơi chúng, bản nhạc, thao tác kéo vào DAW của bạn và plugin.","featuresPage.compare.theyWinTitle":"Họ hơn ở đâu","featuresPage.compare.theyWin":"Scaler 3 là một trạm làm việc lý thuyết âm nhạc rộng hơn nhiều. Synthesia được làm để học chơi trên chính bàn phím của bạn, điều mà Handscore để dành cho phiên bản 1.9. AR Pianist đưa nghệ sĩ piano của nó vào căn phòng của bạn bằng thực tế tăng cường, điều mà Handscore không làm.","featuresPage.compare.fineprint":"Scaler, AR Pianist và Synthesia là nhãn hiệu của các chủ sở hữu tương ứng, vốn không liên kết với Freally Handscore. Nếu một ô nào đó sai, hãy cho chúng tôi biết và chúng tôi sẽ sửa lại.","featuresPage.why.title":"Vì sao nó được làm như vậy","featuresPage.why.rules.title":"Quy tắc, không phải mô hình","featuresPage.why.rules.body":"Mọi phần nhạc, mọi cách bấm ngón và mọi chuyển động đều đến từ các quy tắc, không có mô hình ở bất cứ đâu. Cùng một phong cách và cùng một hạt giống ngẫu nhiên luôn cho ra cùng những phần nhạc, lần nào cũng vậy.","featuresPage.why.drag.title":"Thấy gì thì kéo nấy","featuresPage.why.drag.body":"Các tờ nhạc được vẽ từ chính MIDI mà chúng kéo ra, và đôi tay chơi đúng những nốt đó, nên thứ đáp xuống track của bạn chính là thứ bạn đã xem.","featuresPage.why.real.title":"Làm theo kích thước thật","featuresPage.why.real.body":"Bàn phím có kích thước của một cây đàn piano thật, và mỗi phím xoay trên thanh cân bằng của nó giống như một phím thật.","featuresPage.why.local.title":"Mọi thứ ở lại trên máy của bạn","featuresPage.why.local.body":"Không tài khoản, không đo lường từ xa và không đám mây. Plugin và ứng dụng độc lập không bao giờ lên mạng, và một cổng kiểm tra khi dựng sẽ thất bại nếu mã mạng từng được thêm vào.","featuresPage.coming.title":"Những gì vẫn đang đến","featuresPage.coming.intro":"Nói thẳng, vì một danh sách tính năng giấu đi các thiếu sót thì không đáng đọc. Trang này mô tả phiên bản 1.0, và Handscore được xây từng phiên bản một, nên phần lớn những gì trên trang vẫn chưa được làm. Mỗi phiên bản trên con đường đến 1.0 đều được đánh dấu trạng thái.","featuresPage.limits.title":"Những gì 1.0 không làm","featuresPage.limits.export":"Nó không lưu, xuất hay in MIDI hoặc bản nhạc: một phần nhạc chỉ rời khỏi Handscore bằng cách được kéo vào DAW của bạn.","featuresPage.limits.families":"Nó chơi các cây piano, guitar và guitar bass. Mọi họ nhạc cụ khác sẽ đến dần qua từng phiên bản sau 1.0, cho đến cả ban nhạc ở 2.0.","featuresPage.limits.learn":"Nó không chơi cùng bạn: chơi theo trên chính bàn phím của bạn, và chế độ học, sẽ có ở phiên bản 1.9.","featuresPage.coming.downloads":"Không có bản tải xuống nào trước phiên bản 1.0, và cũng không có trên trang này.","docs.intro":"Tài liệu này lớn dần theo từng phiên bản. Hiện nó mô tả những gì phiên bản 0.2.0 làm được.","docs.start.title":"Bắt đầu","docs.agreement.title":"Thỏa thuận cấp phép","docs.stage.title":"Sân khấu","docs.pianos.title":"Các cây piano","docs.play.title":"Chơi các phím","docs.theme.title":"Sáng và tối","docs.language.title":"Ngôn ngữ","docs.privacy.title":"Quyền riêng tư của bạn","docs.start.p1":"Handscore chạy bên trong DAW của bạn như một nhạc cụ CLAP, VST3 hoặc AU, hoặc chạy riêng như một ứng dụng độc lập. Hãy đặt nó lên một track nhạc cụ.","docs.start.p2":"Chưa có bản tải xuống nào trước phiên bản 1.0.0, và mã nguồn là riêng tư.","docs.agreement.p1":"Lần đầu mở, Handscore hiện ra thỏa thuận cấp phép của nó. Cho đến khi bạn chọn Đồng ý, Handscore không làm gì và không phát ra âm thanh nào.","docs.agreement.p2":"Câu trả lời của bạn được lưu trên máy tính của bạn và dùng chung cho mọi bản Handscore đang mở, trong mọi DAW và trong ứng dụng độc lập. Nếu bạn từ chối, thỏa thuận vẫn ở trên màn hình, sẵn sàng cho bất cứ khi nào bạn đồng ý.","docs.stage.p1":"Bên dưới thanh trên cùng là sân khấu: cây đàn piano bạn đã chọn, với 88 phím, từ A0 đến C8, theo đúng kích thước của một cây đàn piano thật, trải kín chiều rộng cửa sổ. Tên của mỗi phím nằm ở mặt trước của nó — phím trắng in mực tối, phím đen in màu trắng — và ẩn đi khi phím đang được nhấn, nên bạn luôn thấy những nốt nào đang được chơi.","docs.stage.p2":"Nếu máy tính của bạn không thể vẽ 3D, sân khấu sẽ nói rõ điều đó và giải thích cách bật nó lên, thay vì không hiển thị gì.","docs.stage.p3":"Handscore đo xem máy tính của bạn vẽ sân khấu nhanh đến đâu và chọn mức chất lượng mà máy có thể duy trì mượt mà.","docs.pianos.p1":"Bốn cây piano lần lượt lên sân khấu, mỗi lần một cây: Grand Piano, Acoustic Piano, Upright Piano và Honky-Tonk Piano, mỗi cây có hình dáng, lớp hoàn thiện và âm thanh riêng.","docs.pianos.p2":"Nút nhạc cụ ở góc trên bên trái (hoặc P) mở bộ chọn piano. Nghe thử chơi một câu nhạc ngắn trên một cây piano mà không đổi đàn; Chọn đưa nó lên sân khấu, chuyển tiếp mượt mà từ cây trước đó. Lựa chọn của bạn được lưu cùng dự án.","docs.play.p1":"Nhấp vào một phím để nghe nó, hoặc lướt qua các phím để chơi lần lượt từng phím. Mỗi phím đi xuống bằng cách xoay trên thanh cân bằng của nó, được chơi càng mạnh thì xuống càng nhanh, và tên của phím mờ đi khi phím đang xuống rồi hiện lại khi phím nâng lên.","docs.play.p2":"MIDI từ DAW của bạn chơi cây piano và làm các phím của nó chuyển động. Pedal sustain giữ những nốt bạn buông ra cho đến khi bạn nhấc chân khỏi pedal.","docs.theme.p1":"Công tắc Giao diện tối ở góc trên bên phải chuyển cửa sổ sang sáng hoặc tối. Handscore ghi nhớ lựa chọn của bạn, và các ứng dụng Freally khác trên máy tính của bạn cũng vậy.","docs.language.p1":"Handscore nói được mười tám ngôn ngữ và khởi động bằng ngôn ngữ hệ thống của bạn.","docs.privacy.p1":"Plugin và ứng dụng độc lập không bao giờ dùng mạng. Nếu Handscore có lúc dừng đột ngột, một báo cáo ngắn sẽ được lưu trên máy tính của bạn và được đưa ra vào lần mở tiếp theo; không có gì được gửi đi trừ khi bạn chọn báo cáo sự cố.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.documentation":"Tài liệu","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.badge.progress":"v0.2.0 đã xong · tiếp theo là v0.3.0","kit.cta.features":"Xem mọi tính năng","kit.cta.docs":"Đọc tài liệu","kit.price":"Freally Handscore hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.ladder.planned":"Đã lên kế hoạch","kit.ladder.goal":"Mục tiêu","kit.ladder.later":"Về sau","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Mười ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally Handscore, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.status.devVersion":"Đang phát triển · v0.2.0","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.numbers.lead":"Mỗi con số đều được đếm từ chính ứng dụng. Không có gì là ước tính, và không có gì được làm tròn lên.","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.planned":"vẫn chưa được xây dựng","kit.states.goal":"phiên bản mà con đường này hướng tới","kit.states.later":"sau đó, và chưa được lên lịch","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.documentation":"<span class=\"hl-muted\">Cách hoạt động,</span> <span class=\"hl-bright\">từng bước một.</span>","kit.search.placeholder":"Tìm kiếm trong tài liệu","kit.docs.contents":"Mục lục","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally Handscore, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.search.none":"Không có gì trên trang này khớp với điều đó.","kit.zoom.close":"Đóng","changelog.c59c86e0cd28":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.14c84d5c455f":"Những cây piano thật. Giờ đây sân khấu của Handscore có bốn cây piano — một cây đại dương cầm biểu diễn, một cây đại dương cầm phòng khách, một cây piano đứng phòng thu và một cây piano đứng cũ kỹ từ quán rượu miền Viễn Tây — mỗi cây được chiếu sáng như trong phòng thu và mỗi cây có giọng riêng. Nhấp vào một phím hoặc chơi từ DAW của bạn và cây piano sẽ cất tiếng: phím đi xuống, tên của nó mờ dần, và pedal sustain giữ lại những nốt bạn buông ra. Bộ chọn piano cho phép bạn nghe một cây piano trước khi chọn nó.","changelog.6b02e0d363a4":"Đã thêm","changelog.a8f76e859570":"<strong>Bốn cây piano thật.</strong> Grand Piano, Acoustic Piano, Upright Piano và Honky-Tonk Piano, mỗi cây có hình dáng, lớp hoàn thiện và âm thanh riêng, ở cả hai giao diện.","changelog.6f544a8bd67f":"<strong>Chơi các phím.</strong> Nhấp vào một phím để nghe nó, hoặc lướt qua các phím để chơi lần lượt từng phím. MIDI từ DAW của bạn chơi cây piano và làm các phím của nó chuyển động, còn pedal sustain giữ những nốt bạn buông ra cho đến khi bạn nhấc chân khỏi pedal.","changelog.3f265130a08f":"<strong>Phím chuyển động như phím đàn piano.</strong> Mỗi phím đi xuống bằng cách xoay trên thanh cân bằng của nó, được chơi càng mạnh thì xuống càng nhanh, và tên của phím mờ đi khi phím đang xuống rồi hiện lại khi phím nâng lên.","changelog.7fd2c1ed940d":"<strong>Bộ chọn piano.</strong> Nút nhạc cụ ở góc trên bên trái (hoặc P) mở ra bốn thẻ. <em>Nghe thử</em> chơi một câu nhạc ngắn trên cây piano đó mà không đổi đàn; <em>Chọn</em> đưa nó lên sân khấu, chuyển tiếp mượt mà từ cây trước đó. Lựa chọn của bạn được lưu cùng dự án.","changelog.72aa386a33ff":"<strong>Chất lượng vừa với máy tính của bạn.</strong> Handscore đo xem máy tính của bạn vẽ sân khấu nhanh đến đâu và chọn mức chất lượng mà máy có thể duy trì mượt mà.","changelog.1246fc93bca0":"Đã sửa","changelog.58e041aeca75":"<strong>Phím theo kịp ngay cả trên máy tính đang bận.</strong> Một phím được chơi khi máy tính vẽ chậm có thể vẫn ở trên, hoặc tên của nó vẫn mờ một nửa; giờ đây phím luôn dừng đúng ở trạng thái mà cách chơi của bạn để lại.","changelog.e6eef73c000a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span>","changelog.ff94e0b1d59f":"Nền móng. Freally Handscore tải được dưới dạng plugin CLAP và VST3 lẫn ứng dụng độc lập, đề nghị bạn chấp nhận giấy phép, và mở ra trên sân khấu của nó: một bàn phím 88 phím theo đúng kích thước của một cây đàn piano thật, với tên của mọi phím ở mặt trước. Hiện chưa có gì được tạo ra — điều đó sẽ đến cùng những cây piano thật và đôi tay.","changelog.37cee751dc57":"<strong>Plugin và ứng dụng độc lập.</strong> CLAP và VST3 trên Windows (AU được dựng trên máy Mac), và một ứng dụng độc lập mang biểu tượng của Handscore trên thanh tiêu đề và thanh tác vụ.","changelog.bf0d03d43bfd":"<strong>Thỏa thuận cấp phép đến trước tiên.</strong> Cho đến khi bạn đồng ý, Handscore không làm gì. Câu trả lời của bạn được lưu trên máy tính của bạn và dùng chung cho mọi bản đang mở, trong mọi DAW và trong ứng dụng độc lập.","changelog.28bc52fb055e":"<strong>Sân khấu.</strong> Một bàn phím 88 phím, từ A0 đến C8, theo đúng kích thước của một cây đàn piano thật, trải kín chiều rộng cửa sổ. Tên của mỗi phím nằm ở mặt trước của nó — phím trắng in mực tối, phím đen in màu trắng — và ẩn đi khi phím đang được nhấn.","changelog.d51fdbedfc0e":"<strong>Sáng và tối.</strong> Công tắc ở góc trên bên phải; Handscore ghi nhớ lựa chọn của bạn.","changelog.9e0609310c1a":"<strong>Mười tám ngôn ngữ.</strong> Handscore khởi động bằng ngôn ngữ hệ thống của bạn.","changelog.f1cf7c9dfaa8":"<strong>Chế độ xem 3D biết báo khi không thể vẽ.</strong> Một cửa sổ không có WebGL 2 sẽ giải thích cách bật nó lên thay vì không hiển thị gì.","changelog.0fe089d138d3":"<strong>Sự cố được lưu lại, không bao giờ gửi đi.</strong> Nếu Handscore có lúc dừng đột ngột, một báo cáo ngắn sẽ được lưu trên máy tính của bạn cho lần khởi chạy tiếp theo. Không có gì rời khỏi máy tính của bạn trừ khi bạn chọn báo cáo sự cố."};
